func render(scene: LightingScene, width: Int = 192, subject: StudySubject = .sphere) throws -> StudyRenderedFrame {
    let additionalCancellation = additionalCancellation
    let isCancelled = { Task.isCancelled || additionalCancellation() }
    guard !isCancelled() else { throw StudyError.cancelled }
    let renderWidth = subject == .bust ? min(width, PortraitStudyRenderer.maximumWidth) : width
    let key = CacheKey(scene: scene, width: renderWidth, subject: subject)
    if let key {
        // Check before the cache promotes a hit. A cancelled request must
        // neither publish pixels nor change the eviction order.
        guard !isCancelled() else { throw StudyError.cancelled }
        if let cached = frameCache.value(for: key) { return cached }
    }
    if subject == .bust {
        // The mannequin has additional geometry. Do not send it
        // to the sphere-only Metal kernel or claim a validated GPU path.
        let image = try PortraitStudyRenderer.render(scene: scene, width: renderWidth,
                                                    isCancelled: isCancelled)
        guard !isCancelled() else { throw StudyError.cancelled }
        return retain(StudyRenderedFrame(image: image, backend: .cpu), for: key)
    }
    // Eligibility belongs to this request. CPU-only and invalid requests
    // must not initialize or change an unchecked backend.
    let supportsMetal = MetalStudyRenderer.supports(scene, width: width)
    if case .unchecked = state, supportsMetal {
        do {
            guard !isCancelled() else { throw StudyError.cancelled }
            let renderer = try makeComputeBackend()
            try renderer.validate(isCancelled: isCancelled)
            guard !isCancelled() else { throw StudyError.cancelled }
            state = .metal(renderer)
        } catch let error as StudyError {
            // Cancellation and scene errors leave startup retryable.
            // Malformed output confirms a backend failure instead.
            if error != .invalidComputeOutput { throw error }
            selectCPU()
        } catch MetalStudyError.precisionDomain {
            // A precision boundary only routes this request through CPU.
        } catch {
            // Fail closed before observing concurrent cancellation.
            selectCPU()
        }
    }
    guard !isCancelled() else { throw StudyError.cancelled }
    if case .metal(let renderer) = state, supportsMetal {
        do {
            let image = try renderer.render(scene: scene, width: width, isCancelled: isCancelled)
            guard !isCancelled() else { throw StudyError.cancelled }
            return retain(StudyRenderedFrame(image: image, backend: .metal), for: key)
        } catch let error as StudyError {
            // Validation/cancellation is a scene error, not a backend failure.
            if error != .invalidComputeOutput { throw error }
            selectCPU()
        } catch MetalStudyError.precisionDomain {
            // Preserve the validated backend for a later eligible request.
        } catch {
            selectCPU()
        }
    }
    // In particular, a precision-domain fallback must observe cancellation
    // before the CPU renderer constructs its scene and emitter samples.
    guard !isCancelled() else { throw StudyError.cancelled }
    let image = try ReferenceStudyRenderer.render(scene: scene, width: width, isCancelled: isCancelled)
    guard !isCancelled() else { throw StudyError.cancelled }
    return retain(StudyRenderedFrame(image: image, backend: .cpu), for: key)
}

private func selectCPU() {
    state = .cpu
    // A runtime backend failure invalidates its old frames as well. A later
    // hit must not resurrect Metal after the engine has failed closed.
    frameCache.removeAll { $0.backend == .metal }
}

    guard let snapshot = activeRequest else { return }
    // A quick switch back to a completed request can reuse its pixels.
    // Failed frames remain retryable when this view appears again.
    if let frame, frame.request == snapshot, frame.image != nil { return }
    do { try await Task.sleep(nanoseconds: 80_000_000) } catch { return }
    do {
        let rendered = try await StudyRenderEngine.shared.render(scene: snapshot.scene, subject: snapshot.subject)
        guard !Task.isCancelled else { return }
        let study = rendered.image
        let image = Self.makeImage(study)
        guard !Task.isCancelled else { return }
        frame = Frame(request: snapshot, image: image, unsupportedPixels: study.unsupportedPixels,
                      backend: rendered.backend,
                      message: image == nil ? "The rendered image could not be displayed." : nil)
    } catch {
        guard !Task.isCancelled, !(error is CancellationError),
              (error as? StudyError) != .cancelled else { return }
        let message: String
        switch error as? StudyError {
        case .invalidCamera: message = "Move the camera above the panel and away from the subject."
        case .invalidEmitter: message = "Check the aiming direction of each active light."
        default: message = "Check the camera, light positions, and preview settings."
        }
        frame = Frame(request: snapshot, image: nil, unsupportedPixels: 0, backend: nil, message: message)
    }
}

// A previous scene may remain visible while it updates, but a
// different subject or an old error must never stand in for it.
if let frame,
   frame.request == request || (frame.image != nil && frame.request.subject == subject) {
    let isCurrent = frame.request == request
    if let image = frame.image {
        let width = min(geometry.size.width, geometry.size.height * 1.5)
        let updateStatus = activeRequest == nil ? "Light study paused" : "Updating light study"
        let label = isCurrent ? imageLabel : "Previous render. \(imageLabel). \(updateStatus)."
        Image(image, scale: 1, orientation: .up, label: Text(label))
            .resizable().interpolation(.medium)
            .frame(width: width, height: width / 1.5)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .accessibilityLabel(label)
            .accessibilityIdentifier(isCurrent ? "studyPreview" : "studyPreviousPreview")
        if isCurrent, let backendLabel = frame.backendLabel {
            Text(backendLabel).font(.caption2.monospaced())
                .foregroundStyle(.white.opacity(0.8))
                .padding(6).background(.black.opacity(0.75), in: RoundedRectangle(cornerRadius: 6))
                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
                .padding(8).accessibilityIdentifier("studyBackend")
        }
        if isCurrent, frame.unsupportedPixels > 0 {
            Label("\(frame.unsupportedPixels) unsupported pixels (magenta). Move the lights farther away.",
                  systemImage: "exclamationmark.triangle.fill")
                .font(.caption2.weight(.medium))
                .foregroundStyle(.white)
                .padding(8).background(.black.opacity(0.85))
                .accessibilityIdentifier("studyWarning")

.onDisappear { pipeline.invalidate() }
.task(id: work) {
    guard !Task.isCancelled else { return }
    let ticket = pipeline.begin()
    guard let snapshot = activeRequest else { return }
    // A quick switch back to a completed request can reuse its pixels.
    // Failed frames remain retryable when this view appears again.
    if let frame, frame.request == snapshot, frame.image != nil { return }
    // A new attempt shows loading, not an obsolete failure. Retrying
    // never edits the scene or changes its cache identity.
    if frame?.request == snapshot { frame = nil }
    do { try await Task.sleep(nanoseconds: 80_000_000) } catch { return }
    await pipeline.load(ticket: ticket, render: {
        let rendered = try await StudyRenderEngine.shared.render(scene: snapshot.scene, subject: snapshot.subject)
        return .init(image: rendered.image, backendLabel: rendered.backend.rawValue)
    }, convert: Self.makeImage) { completion in
        frame = Frame(request: snapshot, image: completion.image, unsupportedPixels: completion.unsupportedPixels,
                      backendLabel: completion.backendLabel, message: completion.message)
    }

/// Shared cooperative work bound for the two deterministic CPU renderers.
struct StudyPixelCancellation {
    private var pixelsUntilCheck = 0

    /// Call before each pixel, including background/unsupported pixels. A
    /// close-up with many area lights can make a whole scanline expensive;
    /// bound cooperative work between checks without changing pixel sampling.
    @inline(__always)
    mutating func check(_ isCancelled: () -> Bool) throws {
        if pixelsUntilCheck == 0 {
            guard !isCancelled() else { throw StudyError.cancelled }
            pixelsUntilCheck = 8
        }
        pixelsUntilCheck -= 1
    }
